      "name": "index.ts",
      "content": "import { createClient } from "npm:@supabase/supabase-js@2.95.3";

const jsonHeaders = { "Content-Type": "application/json" };

function response(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: jsonHeaders });
}

function keysFromEnvironment(name: string): string[] {
  const value = Deno.env.get(name);
  if (!value) return [];

  try {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === "object") {
      return Object.values(parsed).filter((key): key is string => typeof key === "string");
    }
  } catch {
    // This environment variable is not a JSON key map.
  }

  return [];
}

async function matchesSecret(provided: string, expected: string): Promise<boolean> {
  // Compare fixed-length SHA-256 digests so this check does not short-circuit on
  // the first differing character.
  const encoder = new TextEncoder();
  const [providedDigest, expectedDigest] = await Promise.all([
    crypto.subtle.digest("SHA-256", encoder.encode(provided)),
    crypto.subtle.digest("SHA-256", encoder.encode(expected)),
  ]);
  const left = new Uint8Array(providedDigest);
  const right = new Uint8Array(expectedDigest);
  let difference = 0;
  for (let index = 0; index < left.length; index++) difference |= left[index] ^ right[index];
  return difference === 0;
}

async function hasServiceKey(apikey: string | null): Promise<boolean> {
  if (!apikey) return false;

  const serviceKeys = [
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"),
    ...keysFromEnvironment("SUPABASE_SECRET_KEYS"),
  ].filter((key): key is string => Boolean(key));

  for (const serviceKey of serviceKeys) {
    if (await matchesSecret(apikey, serviceKey)) return true;
  }
  return false;
}

function getAdminKey(): string | undefined {
  return Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? keysFromEnvironment("SUPABASE_SECRET_KEYS")[0];
}

function getPublishableKey(): string | undefined {
  return keysFromEnvironment("SUPABASE_PUBLISHABLE_KEYS")[0] ?? Deno.env.get("SUPABASE_ANON_KEY");
}

Deno.serve(async (req) => {
  if (req.method !== "POST") return response({ error: "Method not allowed" }, 405);

  const url = Deno.env.get("SUPABASE_URL");
  const adminKey = getAdminKey();
  const publishableKey = getPublishableKey();
  if (!url || !adminKey || !publishableKey) {
    console.error("Required Supabase environment variables are unavailable");
    return response({ error: "Server configuration error" }, 500);
  }

  let body: Record<string, unknown>;
  try {
    const parsed = await req.json();
    body = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return response({ error: "Request body must be valid JSON" }, 400);
  }

  const admin = createClient(url, adminKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  let targetUserId: string;
  if (await hasServiceKey(req.headers.get("apikey"))) {
    // A verified secret/service-role key is the only credential allowed to name
    // another user explicitly.
    if (typeof body.user_id !== "string" || body.user_id.length === 0) {
      return response({ error: "user_id is required for service requests" }, 400);
    }
    targetUserId = body.user_id;
  } else {
    const authorization = req.headers.get("Authorization");
    const match = authorization?.match(/^Bearer\s+(.+)$/i);
    if (!match) return response({ error: "Unauthorized" }, 401);

    // getUser validates the access token with Supabase Auth; never trust a
    // decoded JWT or a caller-supplied user_id for this branch.
    const authClient = createClient(url, publishableKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    });
    const { data, error } = await authClient.auth.getUser(match[1]);
    if (error || !data.user) return response({ error: "Unauthorized" }, 401);
    targetUserId = data.user.id;
  }

  // This privileged client is safe here because targetUserId is derived only
  // from a verified access token or a verified service key.
  const { data, error } = await admin
    .from("user_stats")
    .select("*")
    .eq("user_id", targetUserId);

  if (error) {
    console.error("Failed to read user_stats:", error.message);
    return response({ error: "Unable to fetch user stats" }, 500);
  }

  return response(data);
});
